    freq_valya = Counter(valya)
    freq_tolya = Counter(tolya)

    unique_chars = set(freq_valya.keys()).union(set(freq_tolya.keys()))
    spells = []

    for char in unique_chars:
        if char in freq_valya and char in freq_tolya:
            diff = abs(freq_valya[char] - freq_tolya[char])
            if diff % 2 != 0:
                return -1  # Impossible to balance
            else:
                swaps = diff // 2
                spell = (char, char)
                for _ in range(swaps):
                    spells.append(spell)
    return len(spells)

