    removal_order = []
    stack = []

    for char in t:
        if char not in stack:
            stack.append(char)
            removal_order.extend(stack[::-1])
        while stack and stack[-1] != char:
            s.append(stack.pop())
        stack.pop()

    if len(s) != n:
        return "-1", "-1"

    # Reverse the removal order to get the correct sequence
    removal_order.reverse()

